import { useState } from "react";
import { useEstacionamiento } from "../Context/EstacionamientoContext";

function Vehiculos() {
  const { vehiculos, agregarVehiculo } = useEstacionamiento();
  const [form, setForm] = useState({ placa: "", marca: "", modelo: "" });

  function handleGuardar() {
    if (!form.placa) {
      alert("Ingresa las placas");
      return;
    }
    agregarVehiculo(form);
    setForm({ placa: "", marca: "", modelo: "" });
  }

  const inputStyle = {
    padding: "10px 14px",
    border: "1px solid #d1d5db",
    borderRadius: 8,
    fontSize: 14,
    outline: "none"
  };

  return (
    <section>
      <h1 style={{
        fontSize: 28,
        fontWeight: 700,
        color: "#0f172a",
        marginBottom: 24
      }}>
        Registro de Vehículos
      </h1>

      <div style={{
        display: "flex",
        gap: 8,
        flexWrap: "wrap",
        alignItems: "center",
        marginBottom: 24
      }}>
        <input
          style={inputStyle}
          placeholder="Placas"
          value={form.placa}
          onChange={e => setForm({ ...form, placa: e.target.value })}
        />
        <input
          style={inputStyle}
          placeholder="Marca"
          value={form.marca}
          onChange={e => setForm({ ...form, marca: e.target.value })}
        />
        <input
          style={inputStyle}
          placeholder="Modelo"
          value={form.modelo}
          onChange={e => setForm({ ...form, modelo: e.target.value })}
        />
        <button
          onClick={handleGuardar}
          style={{
            padding: "10px 20px",
            background: "#1d4ed8",
            color: "white",
            border: "none",
            borderRadius: 8,
            cursor: "pointer",
            fontSize: 14,
            fontWeight: 600
          }}
        >
          Guardar
        </button>
      </div>

      <h3 style={{
        fontSize: 16,
        color: "#374151",
        marginBottom: 12
      }}>
        Lista:
      </h3>
      <ul style={{
        listStyle: "none",
        padding: 0,
        margin: 0,
        display: "flex",
        flexDirection: "column",
        gap: 8
      }}>
        {vehiculos.map((v, i) => (
          <li
            key={i}
            style={{
              display: "flex",
              alignItems: "center",
              gap: 10,
              background: "white",
              padding: "12px 16px",
              borderRadius: 8,
              boxShadow: "0 1px 3px rgba(0,0,0,0.06)",
              fontSize: 14,
              color: "#1f2937"
            }}
          >
            <span style={{ fontSize: 18 }}>🚗</span>
            {v.placa} — {v.marca} {v.modelo}
          </li>
        ))}
      </ul>
    </section>
  );
}

export default Vehiculos;
